const MIME = {
  '.html':'text/html; charset=utf-8','.css':'text/css; charset=utf-8','.js':'text/javascript; charset=utf-8',
  '.svg':'image/svg+xml','.png':'image/png','.jpg':'image/jpeg','.jpeg':'image/jpeg','.webp':'image/webp',
  '.ico':'image/x-icon','.txt':'text/plain; charset=utf-8','.json':'application/json; charset=utf-8'
};
const COOKIE_NAME = 'jf_session';
const SESSION_MS = 14 * 24 * 60 * 60 * 1000;
const rateBuckets = new Map();

function json(res, status, obj, headers = {}) {
  const body = Buffer.from(JSON.stringify(obj));
  res.writeHead(status, { 'Content-Type':'application/json; charset=utf-8', 'Content-Length':body.length, 'Cache-Control':'no-store', 'X-Content-Type-Options':'nosniff', ...headers });
  res.end(body);
}
function text(res, status, value, headers = {}) {
  const body = Buffer.from(value);
  res.writeHead(status, { 'Content-Type':'text/plain; charset=utf-8', 'Content-Length':body.length, ...headers });
  res.end(body);
}
function safeEqual(a, b) {
  const aa = Buffer.from(String(a)); const bb = Buffer.from(String(b));
  return aa.length === bb.length && crypto.timingSafeEqual(aa, bb);
}
function getCookies(req) {
  const out = {};
  for (const bit of String(req.headers.cookie || '').split(';')) {
    const i = bit.indexOf('='); if (i < 0) continue;
    const k = bit.slice(0, i).trim(); const v = bit.slice(i+1).trim();
    try { out[k] = decodeURIComponent(v); } catch { out[k] = v; }
  }
  return out;
}
function setCookie(res, token, maxAge) {
  const secure = process.env.NODE_ENV === 'production' ? '; Secure' : '';
  res.setHeader('Set-Cookie', `${COOKIE_NAME}=${encodeURIComponent(token)}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${maxAge}${secure}`);
}
function clearCookie(res) {
  const secure = process.env.NODE_ENV === 'production' ? '; Secure' : '';
  res.setHeader('Set-Cookie', `${COOKIE_NAME}=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0${secure}`);
}
function getSession(req) {
  const token = getCookies(req)[COOKIE_NAME];
  if (!token || !/^[A-Za-z0-9_-]{30,100}$/.test(token)) return null;
  const tokenHash = crypto.createHash('sha256').update(token).digest('hex');
  const row = db.prepare(`SELECT s.token_hash,s.csrf_token,s.expires_at,u.id,u.username,u.display_name,u.role,u.status
    FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=?`).get(tokenHash);
  if (!row || row.expires_at < Date.now() || row.status !== 'active') {
    if (row) db.prepare('DELETE FROM sessions WHERE token_hash=?').run(tokenHash);
    return null;
  }
  return { token, tokenHash, csrf: row.csrf_token, user: { id:row.id, username:row.username, display_name:row.display_name, role:row.role } };
}
function createSession(res, userId) {
  const token = crypto.randomBytes(32).toString('base64url');
  const csrf = crypto.randomBytes(24).toString('base64url');
  const expires = Date.now() + SESSION_MS;
  const hash = crypto.createHash('sha256').update(token).digest('hex');
  db.prepare('INSERT INTO sessions(token_hash,user_id,csrf_token,expires_at,created_at) VALUES(?,?,?,?,?)').run(hash,userId,csrf,expires,nowISO());
  setCookie(res, token, Math.floor(SESSION_MS/1000));
  return csrf;
}
function requireAuth(req, res, owner = false) {
  const session = getSession(req);
  if (!session) { json(res, 401, { error:'Требуется авторизация.' }); return null; }
  if (owner && session.user.role !== 'owner') { json(res, 403, { error:'Этот раздел доступен только владельцу сайта.' }); return null; }
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    const origin = req.headers.origin;
    if (origin) {
      try {
        const u = new URL(origin);
        if (u.host !== req.headers.host) { json(res, 403, { error:'Недопустимый источник запроса.' }); return null; }
      } catch { json(res, 403, { error:'Недопустимый источник запроса.' }); return null; }
    }
    if (!safeEqual(req.headers['x-csrf-token'] || '', session.csrf)) { json(res, 403, { error:'Проверка безопасности не пройдена. Обнови страницу.' }); return null; }
  }
  return session;
}
async function readBody(req, limit = 1024*1024) {
  const chunks = []; let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > limit) throw new Error('Слишком большой запрос.');
    chunks.push(chunk);
  }
  if (!chunks.length) return {};
  const raw = Buffer.concat(chunks).toString('utf8');
  const type = String(req.headers['content-type'] || '');
  if (!type.includes('application/json')) throw new Error('Ожидался JSON-запрос.');
  try { return JSON.parse(raw); } catch { throw new Error('Некорректный JSON.'); }
}
function checkRate(key, max, windowMs) {
  const now = Date.now(); const existing = rateBuckets.get(key) || { count:0, start:now };
  if (now - existing.start > windowMs) { existing.count = 0; existing.start = now; }
  existing.count++; rateBuckets.set(key, existing);
  if (rateBuckets.size > 5000) for (const [k,v] of rateBuckets) if (now - v.start > windowMs * 2) rateBuckets.delete(k);
  return existing.count <= max;
}
function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
function renderInline(raw) {
  const links = [];
  let marked = String(raw).replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, (_, label, url) => {
    const i = links.length;
    links.push(`<a href="${escapeHtml(url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(label)}</a>`);
    return `@@SAFE_LINK_${i}@@`;
  });
  marked = escapeHtml(marked)
    .replace(/`([^`]+)`/g, '<code>$1</code>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/(^|[^*])\*([^*]+)\*/g, '$1<em>$2</em>');
  links.forEach((a,i) => { marked = marked.replace(`@@SAFE_LINK_${i}@@`, a); });
  return marked;
}
function renderMarkdown(markdown) {
  const lines = String(markdown || '').replace(/\r/g,'').split('\n');
  const out = []; let para = []; let list = []; let numbered = [];
  const flushPara = () => { if (para.length) { out.push(`<p class="copy-bubble">${renderInline(para.join(' '))}</p>`); para=[]; } };
  const flushList = () => { if (list.length) { out.push(`<ul class="liquid-list">${list.map(x=>`<li>${renderInline(x)}</li>`).join('')}</ul>`); list=[]; } };
  const flushNumbered = () => { if (numbered.length) { out.push(numbered.map(x=>`<p class="copy-bubble rule-bubble">${renderInline(x)}</p>`).join('')); numbered=[]; } };
  for (const line0 of lines) {
    const line = line0.trim();
    if (!line) { flushPara(); flushList(); flushNumbered(); continue; }
    if (/^#{1,3}\s/.test(line)) {
      flushPara(); flushList(); flushNumbered();
      const level = line.match(/^#+/)[0].length; const title = line.replace(/^#{1,3}\s+/,'');
      out.push(`<h${level+1} class="content-heading">${renderInline(title)}</h${level+1}>`); continue;
    }
    if (/^[-*]\s+/.test(line)) { flushPara(); flushNumbered(); list.push(line.replace(/^[-*]\s+/,'')); continue; }
    if (/^\d+(?:\.\d+)+\.\s+/.test(line)) { flushPara(); flushList(); numbered.push(line); continue; }
    if (/^>\s?/.test(line)) { flushPara(); flushList(); flushNumbered(); out.push(`<blockquote class="quote-bubble">${renderInline(line.replace(/^>\s?/,''))}</blockquote>`); continue; }
    flushList(); flushNumbered(); para.push(line);
  }
  flushPara(); flushList(); flushNumbered();
  return out.join('\n');
}
function sanitizeSlug(s) { return String(s || '').toLowerCase().trim().normalize('NFKD').replace(/[^a-z0-9-]+/g,'-').replace(/^-+|-+$/g,'').slice(0,48); }
