async function passwordHash(password, saltHex) {
  const salt = saltHex ? Buffer.from(saltHex, 'hex') : crypto.randomBytes(16);
  const derived = await scrypt(password, salt, 64);
  return { salt: salt.toString('hex'), hash: Buffer.from(derived).toString('hex') };
}
function cleanText(value, max = 2000) { return String(value ?? '').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g,'').trim().slice(0,max); }
function parseJsonSafe(raw) { try { return JSON.parse(raw); } catch { return {}; } }

async function createBackup(kind = 'manual') {
  const stamp = new Date().toISOString().replace(/[:.]/g,'-');
  const name = `justice-faite-${kind}-${stamp}.sqlite`;
  const dest = path.join(BACKUP_DIR, name);
  // VACUUM INTO creates a consistent, standalone SQLite snapshot, including WAL changes.
  db.exec(`VACUUM INTO '${dest.replace(/'/g,"''")}'`);
  const files = fs.readdirSync(BACKUP_DIR).filter(f => /^justice-faite-(daily|manual)-.*\.sqlite$/.test(f));
  for (const category of ['daily','manual']) {
    const group = files.filter(f => f.startsWith(`justice-faite-${category}-`)).sort().reverse();
    const keep = category === 'daily' ? 14 : 20;
    for (const old of group.slice(keep)) { try { fs.unlinkSync(path.join(BACKUP_DIR, old)); } catch {} }
  }
  return { name, size:fs.statSync(dest).size, created_at:nowISO(), kind };
}
async function dailyBackup() {
  try {
    db.prepare('DELETE FROM sessions WHERE expires_at < ?').run(Date.now());
    const files = fs.readdirSync(BACKUP_DIR).filter(f => f.startsWith('justice-faite-daily-')).sort();
    const last = files.at(-1);
    if (!last || Date.now() - fs.statSync(path.join(BACKUP_DIR,last)).mtimeMs > 23*60*60*1000) await createBackup('daily');
  } catch (e) { console.error('[backup] daily backup failed:', e.message); }
}

async function handleApi(req, res, url) {
  const method = req.method;
  const p = url.pathname;
  if (p === '/healthz' && method === 'GET') return json(res, 200, { ok:true, version:'0.2.0' });

  if (p === '/api/setup/status' && method === 'GET') return json(res, 200, { needed:ownerCount() === 0 });
  if (p === '/api/setup/owner' && method === 'POST') {
    if (!checkRate(`owner-setup:${req.socket.remoteAddress}`, 10, 60*60*1000)) return json(res,429,{error:'Слишком много попыток первичной настройки. Попробуй позже.'});
    if (ownerCount() > 0) return json(res, 409, { error:'Владелец сайта уже создан.' });
    const body = await readBody(req);
    const key = String(body.setupKey || '');
    if (!safeEqual(key, setupKey)) return json(res, 403, { error:'Ключ первичной настройки не подходит. Проверь логи сервера.' });
    const username = cleanText(body.username, 24).replace(/\s/g,'');
    const displayName = cleanText(body.displayName, 40) || username;
    const password = String(body.password || '');
    if (!/^[a-zA-Z0-9_.-]{3,24}$/.test(username)) return json(res, 400, { error:'Логин: 3–24 символа, латиница, цифры, точка, дефис или подчёркивание.' });
    if (password.length < 10 || password.length > 128) return json(res, 400, { error:'Пароль должен содержать от 10 до 128 символов.' });
    const { salt, hash } = await passwordHash(password);
    try {
      const result = db.prepare(`INSERT INTO users(username,display_name,password_salt,password_hash,role,status,created_at) VALUES(?,?,?,?, 'owner','active',?)`)
        .run(username, displayName, salt, hash, nowISO());
      if (fs.existsSync(setupKeyFile)) fs.unlinkSync(setupKeyFile);
      logAudit(Number(result.lastInsertRowid), 'owner_setup', username, 'Первичная настройка владельца');
      const csrf = createSession(res, Number(result.lastInsertRowid));
      return json(res, 201, { ok:true, csrf, user:{ id:Number(result.lastInsertRowid), username, display_name:displayName, role:'owner' } });
    } catch (e) { return json(res, 409, { error:'Такой логин уже существует.' }); }
  }

  if (p === '/api/public' && method === 'GET') {
    const pages = db.prepare('SELECT * FROM pages WHERE visible=1 ORDER BY nav_order, title').all().map(publicPage);
    const settings = getSettings();
    return json(res, 200, { pages, updates:listPublicUpdates(5), settings:{ site_name:settings.site_name, hero_title:settings.hero_title, hero_description:settings.hero_description, hero_badge:settings.hero_badge, member_count:settings.member_count, group_url:settings.group_url, info_url:settings.info_url, bot_username:settings.bot_username, bot_start_rest:settings.bot_start_rest, bot_start_tokens:settings.bot_start_tokens, bot_start_anonymous:settings.bot_start_anonymous, announcement:settings.announcement, comments_enabled:settings.comments_enabled, registrations_enabled:settings.registrations_enabled, last_bot_sync:settings.last_bot_sync } });
  }

  if (p === '/api/me' && method === 'GET') {
    const session = getSession(req);
    if (!session) return json(res, 200, { user:null, csrf:null });
    return json(res, 200, { user:session.user, csrf:session.csrf });
  }
  if (p === '/api/auth/register' && method === 'POST') {
    const settings = getSettings();
    if (settings.registrations_enabled !== 'true') return json(res, 403, { error:'Регистрация временно закрыта владельцем сайта.' });
    if (!checkRate(`register:${req.socket.remoteAddress}`, 5, 60*60*1000)) return json(res, 429, { error:'Слишком много попыток. Попробуй позже.' });
    const body = await readBody(req);
    const username = cleanText(body.username, 24).replace(/\s/g,'');
    const displayName = cleanText(body.displayName, 40) || username;
    const password = String(body.password || '');
    if (!/^[a-zA-Z0-9_.-]{3,24}$/.test(username)) return json(res, 400, { error:'Логин: 3–24 символа, латиница, цифры, точка, дефис или подчёркивание.' });
    if (password.length < 10 || password.length > 128) return json(res, 400, { error:'Пароль должен содержать от 10 до 128 символов.' });
    const { salt, hash } = await passwordHash(password);
    try {
      const result = db.prepare(`INSERT INTO users(username,display_name,password_salt,password_hash,role,status,created_at) VALUES(?,?,?,?, 'member','active',?)`)
        .run(username, displayName, salt, hash, nowISO());
      const csrf = createSession(res, Number(result.lastInsertRowid));
      return json(res, 201, { ok:true, csrf, user:{ id:Number(result.lastInsertRowid), username, display_name:displayName, role:'member' } });
    } catch { return json(res, 409, { error:'Этот логин уже занят.' }); }
  }
  if (p === '/api/auth/login' && method === 'POST') {
    if (!checkRate(`login:${req.socket.remoteAddress}`, 10, 15*60*1000)) return json(res, 429, { error:'Слишком много попыток входа. Подожди 15 минут.' });
    const body = await readBody(req);
    const username = cleanText(body.username, 24);
    const password = String(body.password || '');
    const user = db.prepare('SELECT * FROM users WHERE username=? COLLATE NOCASE').get(username);
    if (!user || user.status !== 'active') return json(res, 401, { error:'Неверный логин или пароль.' });
    const { hash } = await passwordHash(password, user.password_salt);
    if (!safeEqual(hash, user.password_hash)) return json(res, 401, { error:'Неверный логин или пароль.' });
    const csrf = createSession(res, user.id);
    return json(res, 200, { ok:true, csrf, user:{ id:user.id, username:user.username, display_name:user.display_name, role:user.role } });
  }
  if (p === '/api/auth/logout' && method === 'POST') {
    const session = requireAuth(req,res); if (!session) return;
    db.prepare('DELETE FROM sessions WHERE token_hash=?').run(session.tokenHash);
    clearCookie(res); return json(res, 200, { ok:true });
  }

  const pageMatch = p.match(/^\/api\/pages\/([a-z0-9-]+)$/);
  if (pageMatch && method === 'GET') {
    const page = getPage(pageMatch[1]);
    if (!page) return json(res,404,{error:'Раздел не найден.'});
    return json(res,200,{page:{...publicPage(page),html:renderMarkdown(page.content)}});
  }
  const commentsMatch = p.match(/^\/api\/pages\/([a-z0-9-]+)\/comments$/);
  if (commentsMatch && method === 'GET') {
    const page = getPage(commentsMatch[1]); if (!page) return json(res,404,{error:'Раздел не найден.'});
    const session = getSession(req);
    let rows = db.prepare(`SELECT c.id,c.body,c.status,c.created_at,u.display_name FROM comments c JOIN users u ON u.id=c.user_id WHERE c.page_slug=? AND c.status='approved' ORDER BY c.created_at DESC LIMIT 50`).all(commentsMatch[1]);
    if (session) {
      const own = db.prepare(`SELECT c.id,c.body,c.status,c.created_at,u.display_name FROM comments c JOIN users u ON u.id=c.user_id WHERE c.page_slug=? AND c.user_id=? AND c.status='pending' ORDER BY c.created_at DESC LIMIT 10`).all(commentsMatch[1],session.user.id);
      rows = [...own, ...rows];
    }
    return json(res,200,{comments:rows});
  }
  if (p === '/api/comments' && method === 'POST') {
    const session = requireAuth(req,res); if (!session) return;
    if (getSettings().comments_enabled !== 'true') return json(res,403,{error:'Комментарии временно отключены владельцем.'});
    if (!checkRate(`comment:${session.user.id}`, 3, 60*60*1000)) return json(res,429,{error:'Можно отправить не больше трёх комментариев в час.'});
    const body = await readBody(req);
    const slug = sanitizeSlug(body.pageSlug);
    const page = getPage(slug); if (!page) return json(res,404,{error:'Раздел не найден.'});
    const content = cleanText(body.body, 1200);
    if (content.length < 3) return json(res,400,{error:'Комментарий слишком короткий.'});
    const result = db.prepare(`INSERT INTO comments(page_slug,user_id,body,status,created_at,updated_at) VALUES(?,?,?,'pending',?,?)`).run(slug,session.user.id,content,nowISO(),nowISO());
    return json(res,201,{ok:true,id:Number(result.lastInsertRowid),message:'Комментарий отправлен на проверку владельцу сайта.'});
  }

  if (p === '/api/admin/data' && method === 'GET') {
    const session = requireAuth(req,res,true); if (!session) return;
    const pages = db.prepare('SELECT * FROM pages ORDER BY nav_order,title').all();
    const comments = db.prepare(`SELECT c.*,u.username,u.display_name FROM comments c JOIN users u ON u.id=c.user_id ORDER BY CASE c.status WHEN 'pending' THEN 0 ELSE 1 END,c.created_at DESC LIMIT 200`).all();
    const users = db.prepare(`SELECT id,username,display_name,role,status,created_at FROM users ORDER BY created_at DESC LIMIT 300`).all();
    const backups = listBackups();
    const updates = db.prepare('SELECT id,title,body,page_slug,published,created_at,updated_at FROM site_updates ORDER BY created_at DESC,id DESC LIMIT 100').all();
    const stats = { users:db.prepare('SELECT count(*) n FROM users').get().n, comments:db.prepare('SELECT count(*) n FROM comments').get().n, pending:db.prepare("SELECT count(*) n FROM comments WHERE status='pending'").get().n };
    return json(res,200,{pages,settings:getSettings(),comments,users,backups,updates,stats});
  }
  if (p === '/api/admin/pages' && method === 'POST') {
    const session = requireAuth(req,res,true); if (!session) return;
    const body = await readBody(req);
    const slug = sanitizeSlug(body.slug || body.title);
    const title = cleanText(body.title,80);
    if (!slug || !title) return json(res,400,{error:'Укажи название и адрес страницы.'});
    try {
      db.prepare(`INSERT INTO pages(slug,title,eyebrow,description,content,source_url,visible,nav_order,updated_at) VALUES(?,?,?,?,?,?,1,?,?)`)
        .run(slug,title,cleanText(body.eyebrow,80),cleanText(body.description,300),String(body.content||''),validHttpUrl(body.source_url),Number(body.nav_order)||100,nowISO());
      logAudit(session.user.id,'page_create',slug,title);
      return json(res,201,{ok:true,slug});
    } catch { return json(res,409,{error:'Такая страница уже существует.'}); }
  }
  const adminPageMatch = p.match(/^\/api\/admin\/pages\/([a-z0-9-]+)$/);
  if (adminPageMatch && method === 'PUT') {
    const session = requireAuth(req,res,true); if (!session) return;
    const body = await readBody(req);
    const slug = adminPageMatch[1];
    const exists = getAdminPage(slug); if (!exists) return json(res,404,{error:'Страница не найдена.'});
    const updatedAt = nowISO();
    db.prepare(`UPDATE pages SET title=?,eyebrow=?,description=?,content=?,source_url='',visible=?,nav_order=?,updated_at=? WHERE slug=?`)
      .run(cleanText(body.title,80)||exists.title,cleanText(body.eyebrow,80),cleanText(body.description,300),String(body.content??exists.content),body.visible===false?0:1,Number.isFinite(Number(body.nav_order))?Number(body.nav_order):exists.nav_order,updatedAt,slug);
    let updateId = null;
    if (body.releaseNote && body.releaseNote.publish === true) {
      const noteTitle = cleanText(body.releaseNote.title,100);
      const noteBody = cleanText(body.releaseNote.body,600);
      if (noteTitle && noteBody) {
        const result = db.prepare('INSERT INTO site_updates(title,body,page_slug,published,created_at,updated_at) VALUES(?,?,?,1,?,?)')
          .run(noteTitle,noteBody,slug,updatedAt,updatedAt);
        updateId = Number(result.lastInsertRowid);
      }
    }
    logAudit(session.user.id,'page_update',slug,'Содержимое страницы обновлено');
    if (updateId) logAudit(session.user.id,'site_update_publish',String(updateId),'Официальное обновление опубликовано');
    return json(res,200,{ok:true,updateId});
  }
  if (adminPageMatch && method === 'DELETE') {
    const session = requireAuth(req,res,true); if (!session) return;
    const slug = adminPageMatch[1];
    if (['rules','purge','norm','rest','games','game-rules','guide','tokens','anonymous'].includes(slug)) return json(res,400,{error:'Основной раздел нельзя удалить. Его можно скрыть в настройках страницы.'});
    db.prepare('DELETE FROM pages WHERE slug=?').run(slug);
    logAudit(session.user.id,'page_delete',slug,'Страница удалена');
    return json(res,200,{ok:true});
  }
  if (p === '/api/admin/updates' && method === 'POST') {
    const session = requireAuth(req,res,true); if (!session) return;
    const body = await readBody(req);
    const title = cleanText(body.title,100);
    const note = cleanText(body.body,600);
    if (!title || !note) return json(res,400,{error:'Укажи заголовок и описание обновления.'});
    const published = body.published === true ? 1 : 0;
    const stamp = nowISO();
    const result = db.prepare('INSERT INTO site_updates(title,body,page_slug,published,created_at,updated_at) VALUES(?,?,?,?,?,?)').run(title,note,'',published,stamp,stamp);
    const id = Number(result.lastInsertRowid);
    logAudit(session.user.id,'site_update_create',String(id),published?'Обновление опубликовано':'Обновление сохранено скрытым');
    return json(res,201,{ok:true,id});
  }
  const updateAdminMatch = p.match(/^\/api\/admin\/updates\/(\d+)$/);
  if (updateAdminMatch && method === 'PATCH') {
    const session = requireAuth(req,res,true); if (!session) return;
    const id = Number(updateAdminMatch[1]);
    const current = db.prepare('SELECT * FROM site_updates WHERE id=?').get(id);
    if (!current) return json(res,404,{error:'Обновление не найдено.'});
    const body = await readBody(req);
    const title = 'title' in body ? cleanText(body.title,100) : current.title;
    const note = 'body' in body ? cleanText(body.body,600) : current.body;
    const published = 'published' in body ? (body.published === true ? 1 : 0) : current.published;
    if (!title || !note) return json(res,400,{error:'Заголовок и описание не могут быть пустыми.'});
    db.prepare('UPDATE site_updates SET title=?,body=?,published=?,updated_at=? WHERE id=?').run(title,note,published,nowISO(),id);
    logAudit(session.user.id,'site_update_update',String(id),published?'Обновление опубликовано':'Обновление скрыто');
    return json(res,200,{ok:true});
  }
  if (updateAdminMatch && method === 'DELETE') {
    const session = requireAuth(req,res,true); if (!session) return;
    const id = Number(updateAdminMatch[1]);
    db.prepare('DELETE FROM site_updates WHERE id=?').run(id);
    logAudit(session.user.id,'site_update_delete',String(id),'Официальное обновление удалено');
    return json(res,200,{ok:true});
  }

  if (p === '/api/admin/settings' && method === 'PUT') {
    const session = requireAuth(req,res,true); if (!session) return;
    const body = await readBody(req);
    const allowed = ['site_name','hero_title','hero_description','hero_badge','member_count','group_url','info_url','bot_username','bot_start_rest','bot_start_tokens','bot_start_anonymous','announcement','comments_enabled','registrations_enabled'];
    const update = {};
    for (const key of allowed) if (key in body) update[key] = String(body[key] ?? '').slice(0, key==='hero_description'||key==='announcement'?500:200);
    if ('member_count' in update && update.member_count && !/^\d{1,7}$/.test(update.member_count)) return json(res,400,{error:'Количество участников должно быть целым числом.'});
    for (const key of ['group_url','info_url']) if (key in update) update[key] = validHttpUrl(update[key]);
    if ('bot_username' in update) update.bot_username = update.bot_username.replace(/^@/,'').replace(/[^A-Za-z0-9_]/g,'').slice(0,32);
    for (const key of ['bot_start_rest','bot_start_tokens','bot_start_anonymous']) if (key in update) update[key] = update[key].replace(/[^A-Za-z0-9_-]/g,'').slice(0,64);
    for (const key of ['comments_enabled','registrations_enabled']) if (key in update) update[key] = update[key]==='true'?'true':'false';
    setSettings(update); logAudit(session.user.id,'settings_update','site',Object.keys(update).join(','));
    return json(res,200,{ok:true,settings:getSettings()});
  }
  const commentAdminMatch = p.match(/^\/api\/admin\/comments\/(\d+)$/);
  if (commentAdminMatch && method === 'PATCH') {
    const session = requireAuth(req,res,true); if (!session) return;
    const body = await readBody(req); const status = body.status === 'approved' ? 'approved' : 'rejected';
    db.prepare('UPDATE comments SET status=?,updated_at=? WHERE id=?').run(status,nowISO(),Number(commentAdminMatch[1]));
    logAudit(session.user.id,'comment_moderate',commentAdminMatch[1],status);
    return json(res,200,{ok:true});
  }
  if (commentAdminMatch && method === 'DELETE') {
    const session = requireAuth(req,res,true); if (!session) return;
    db.prepare('DELETE FROM comments WHERE id=?').run(Number(commentAdminMatch[1]));
    logAudit(session.user.id,'comment_delete',commentAdminMatch[1],'Комментарий удалён');
    return json(res,200,{ok:true});
  }
  const userAdminMatch = p.match(/^\/api\/admin\/users\/(\d+)$/);
  if (userAdminMatch && method === 'PATCH') {
    const session = requireAuth(req,res,true); if (!session) return;
    const body = await readBody(req); const id = Number(userAdminMatch[1]);
    const target = db.prepare('SELECT id,role FROM users WHERE id=?').get(id);
    if (!target) return json(res,404,{error:'Пользователь не найден.'});
    if (target.role === 'owner') return json(res,400,{error:'Нельзя заблокировать владельца сайта.'});
    const status = body.status === 'blocked' ? 'blocked' : 'active';
    db.prepare('UPDATE users SET status=? WHERE id=?').run(status,id);
    if (status === 'blocked') db.prepare('DELETE FROM sessions WHERE user_id=?').run(id);
    logAudit(session.user.id,'user_status',String(id),status);
    return json(res,200,{ok:true});
  }
  if (p === '/api/admin/backups' && method === 'GET') {
    const session = requireAuth(req,res,true); if (!session) return;
    return json(res,200,{backups:listBackups()});
  }
  if (p === '/api/admin/backups' && method === 'POST') {
    const session = requireAuth(req,res,true); if (!session) return;
    const backup = await createBackup('manual');
    logAudit(session.user.id,'backup_create',backup.name,'Резервная копия создана');
    return json(res,201,{ok:true,backup});
  }
  const backupMatch = p.match(/^\/api\/admin\/backups\/([A-Za-z0-9_.-]+)$/);
  if (backupMatch && method === 'GET') {
    const session = requireAuth(req,res,true); if (!session) return;
    const name = backupMatch[1];
    if (!/^justice-faite-(daily|manual)-[A-Za-z0-9_.-]+\.sqlite$/.test(name)) return json(res,400,{error:'Недопустимое имя файла.'});
    const file = path.join(BACKUP_DIR,name);
    if (!fs.existsSync(file)) return json(res,404,{error:'Файл резервной копии не найден.'});
    res.writeHead(200,{'Content-Type':'application/vnd.sqlite3','Content-Disposition':`attachment; filename="${name}"`,'Content-Length':fs.statSync(file).size,'Cache-Control':'no-store'});
    fs.createReadStream(file).pipe(res); return;
  }
  if (p === '/api/bot/stats' && method === 'POST') {
    const token = String(req.headers.authorization || '').replace(/^Bearer\s+/i,'');
    if (!process.env.BOT_SYNC_TOKEN || !safeEqual(token,process.env.BOT_SYNC_TOKEN)) return json(res,401,{error:'Недействительный токен синхронизации.'});
    const body = await readBody(req);
    const n = Number(body.memberCount);
    if (!Number.isInteger(n) || n < 0 || n > 10000000) return json(res,400,{error:'Некорректное количество участников.'});
    setSettings({member_count:String(n),last_bot_sync:nowISO()});
    return json(res,200,{ok:true,member_count:n});
  }
  return json(res,404,{error:'API route not found'});
}

function listBackups() {
  return fs.readdirSync(BACKUP_DIR).filter(f => /^justice-faite-(daily|manual)-.*\.sqlite$/.test(f)).map(name => {
    const st = fs.statSync(path.join(BACKUP_DIR,name));
    return {name,size:st.size,created_at:st.mtime.toISOString(),kind:name.includes('-daily-')?'daily':'manual'};
  }).sort((a,b)=>b.created_at.localeCompare(a.created_at));
}

async function serveStatic(req, res, pathname) {
  const cleanPath = decodeURIComponent(pathname.split('?')[0]);
  let relative = cleanPath === '/' ? 'index.html' : cleanPath.replace(/^\/+/, '');
  if (relative.includes('..') || relative.includes('\\') || relative.startsWith('data')) return text(res,404,'Not found');
  let file = path.resolve(PUBLIC_DIR, relative);
  if (!file.startsWith(PUBLIC_DIR + path.sep) && file !== path.join(PUBLIC_DIR,'index.html')) return text(res,404,'Not found');
  if (!fs.existsSync(file) || fs.statSync(file).isDirectory()) file = path.join(PUBLIC_DIR,'index.html');
  const ext = path.extname(file).toLowerCase();
  const headers = { 'Content-Type':MIME[ext] || 'application/octet-stream', 'X-Content-Type-Options':'nosniff', 'Referrer-Policy':'strict-origin-when-cross-origin', 'X-Frame-Options':'DENY', 'Permissions-Policy':'camera=(), microphone=(), geolocation=()', 'Content-Security-Policy':"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com data:; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'", 'Cache-Control':ext==='.html'?'no-store':'public, max-age=3600' };
  res.writeHead(200,headers);
  fs.createReadStream(file).pipe(res);
}

const server = http.createServer(async (req,res) => {
  try {
    const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
    if (url.pathname.startsWith('/api/') || url.pathname === '/healthz') {
      await handleApi(req,res,url);
      return;
    }
    if (req.method !== 'GET' && req.method !== 'HEAD') return text(res,405,'Method not allowed');
    await serveStatic(req,res,url.pathname);
  } catch (e) {
    console.error('[server error]', e.stack || e.message);
    if (!res.headersSent) json(res,500,{error:'Внутренняя ошибка сервера.'}); else res.end();
  }
});

const port = Number(process.env.PORT || 3000);
server.listen(port,'0.0.0.0', async () => {
  console.log(`Justice Faite Portal 0.2.0 listening on 0.0.0.0:${port}`);
  await dailyBackup();
});
const backupTimer = setInterval(dailyBackup, 60*60*1000);
backupTimer.unref();

async function shutdown() {
  clearInterval(backupTimer);
  server.close(() => {
    try { db.exec('PRAGMA wal_checkpoint(TRUNCATE)'); } catch {}
    try { db.close(); } catch {}
    process.exit(0);
  });
  setTimeout(()=>process.exit(1), 10000).unref();
}
process.on('SIGTERM',shutdown);
process.on('SIGINT',shutdown);
